178	        torch::TensorOptions().device(param.device()).dtype(torch::kFloat32));
179	    std::vector<torch::Tensor> vp{param};
180	    std::vector<torch::Tensor> vm{exp_avg};
181	    std::vector<torch::Tensor> vv{exp_avg_sq};
182	    std::vector<torch::Tensor> vs{s};
183	    std::vector<torch::Tensor> vpi{param_init};
