201	void launch_multi_tensor_prodigy_fused_reduce_step(
202	    std::vector<torch::Tensor>& params, std::vector<torch::Tensor>& grads, std::vector<torch::Tensor>& param_inits, std::vector<torch::Tensor>& exp_avgs, std::vector<torch::Tensor>& exp_avg_sqs, std::vector<torch::Tensor>& s_bufs, std::vector<float>& bc1s, std::vector<float>& bc2s, torch::Tensor d_lr_buf, float beta1, float beta2, float lr, float wd, float eps
203	) {
204	    if (params.empty()) return;
205	    auto dev = params[0].device();
206	    float d_prev = d_lr_buf.item<float>();
207	
208	    // Phase 1: accumulate r and s across all tensors
209	    auto r_sum = torch::zeros({}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
210	    auto s_sum = torch::zeros({}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
211	#if defined(__HIPCC__)
212	    // LIVE (hipcc): §5 DPP r/s reduction, one launch per tensor → 2-float AGENT
213	    // accumulator [r,s]. d_prev / d_prev² folded in the kernel; identical to ATen.
214	    auto rs_acc = torch::zeros({2}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
215	    auto stream = at::hip::getCurrentHIPStream();
216	    for (size_t i = 0; i < params.size(); i++) {
217	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
218	        auto gf = grads[i].to(torch::kFloat32).contiguous();
219	        auto pf = params[i].to(torch::kFloat32).contiguous();
220	        auto pif = param_inits[i].to(torch::kFloat32).contiguous();
221	        // 64-bit safe element count + grid sizing (Stage 1).
222	        const int64_t n = static_cast<int64_t>(gf.numel());
223	        dim3 block(256), grid(static_cast<unsigned>(
224	            std::min<int64_t>(1024, (n + 255) / 256)));
225	        hipLaunchKernelGGL(native::prodigy_gfx942_rs_reduce, grid, block, 0, stream,
226	                           gf.data_ptr<float>(), pf.data_ptr<float>(),
227	                           pif.data_ptr<float>(),
228	                           rs_acc.data_ptr<float>(), rs_acc.data_ptr<float>() + 1,
229	                           d_prev, n);
230	        SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
231	    }
232	    r_sum += rs_acc[0];
233	    s_sum += rs_acc[1];
234	#else
235	    for (size_t i = 0; i < params.size(); i++) {
236	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
237	        auto gf = grads[i].to(torch::kFloat32);
238	        auto delta = (param_inits[i] - params[i]).to(torch::kFloat32);
239	        r_sum += (gf * delta).sum() * d_prev;
240	        s_sum += gf.abs().sum() * (d_prev * d_prev);
241	    }
242	#endif
243	
244	    // Phase 2: update d
245	    auto candidate = r_sum / (s_sum.abs() + 1e-12f);
246	    d_lr_buf.copy_(torch::maximum(d_lr_buf.new_full({}, d_prev), candidate));
247	    float d_val = d_lr_buf.item<float>();
248	
249	    // Phase 3: apply Adam with d as effective lr
250	    for (size_t i = 0; i < params.size(); i++) {
251	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
252	        auto gf = d_val * grads[i].to(torch::kFloat32);
253	        prim::ema_update_inplace(exp_avgs[i], gf, beta1);
254	        prim::ema_sq_update_inplace(exp_avg_sqs[i], gf, beta2);
255	        s_bufs[i].add_(grads[i].to(torch::kFloat32), d_val);
256	        prim::adam_apply_inplace(params[i], exp_avgs[i], exp_avg_sqs[i],
257	                                 d_val, bc1s[i], bc2s[i], eps, wd);
258	    }
