341	// Stage-1 NaN/Inf gradient sanitization (mirror of sm_90 sg_sanitize_grad).
342	// Identity unless built with -DSG_SANITIZE_NONFINITE=1; default byte-identical.
343	// Applied on the APPLY path's grad read only (the r/s reduction is unchanged).
344	#ifndef SG_SANITIZE_NONFINITE
345	#define SG_SANITIZE_NONFINITE 0
346	#endif
347	__device__ __forceinline__ float sg_sanitize_grad(float g) {
348	#if SG_SANITIZE_NONFINITE
349	    return __builtin_isfinite(g) ? g : 0.0f;
350	#else
351	    return g;
352	#endif
353	}
354	static constexpr int kWave = 64;   // == amd::kWave (CDNA3 wavefront width)
355	
356	__device__ __forceinline__ float dabsf(float x) { return __builtin_fabsf(x); }
357	
358	// Block (workgroup) prodigy r/s reduction over `[0..n)`, two AGENT atomics.
359	// r_i = g_i·(p_init_i − p_i)·d_prev ;  s_i = d_prev²·|g_i|.
360	// blockDim.x must be a multiple of kWave and <= kWave*kWave (<= 4096); LDS holds
361	// one float per wavefront per quantity (<= 2*64 floats).
362	__device__ __forceinline__ void prodigy_rs_block(
363	    const float* __restrict__ g, const float* __restrict__ p,
364	    const float* __restrict__ p_init, float* __restrict__ r_acc,
365	    float* __restrict__ s_acc, float d_prev, int64_t n)
366	{
367	    // LDS/lane bookkeeping is LOCAL to the block (<= 4096 threads) → int. The
368	    // GLOBAL element index/stride is int64 so the reduction cannot wrap (Stage 1).
369	    const int tid    = static_cast<int>(threadIdx.x);
370	    const int lane   = tid % kWave;
371	    const int waveId = tid / kWave;
372	    const int wpb    = static_cast<int>(blockDim.x) / kWave;
373	    const int64_t gtid   = static_cast<int64_t>(blockIdx.x) * blockDim.x + tid;
374	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
375	    const float d2   = d_prev * d_prev;
376	
377	    // VECTORIZED reduction body (WS5/item 6): widen the 3-buffer read to 128-bit
378	    // (f32x4 / dwordx4) memory access — was three scalar loads/iter. The 4 lanes
379	    // accumulate the IDENTICAL scalar partials (r_i = g_i·(p_init_i−p_i)·d_prev,
380	    // s_i = d²·|g_i|), so the per-thread partials are bit-identical to the scalar
381	    // form — only the access width changes. A scalar TAIL covers the n%4 remainder.
382	    // NONTEMPORAL POLICY: g is the read-once grad → streaming (nontemporal); p is
383	    // the current param (read here, written by the apply → recurring) and p_init
384	    // is re-read every step → both CACHED (keep L2-resident).
385	    using f32x4 = amd::f32x4;
386	    const int64_t n4v = n & ~static_cast<int64_t>(3);   // largest mult of 4 <= n
387	    const auto* g4  = reinterpret_cast<const f32x4*>(g);
388	    const auto* p4  = reinterpret_cast<const f32x4*>(p);
